<?php
require_once __DIR__.'/config/auth.php';require_staff();require_once __DIR__.'/config/ventas.php';
$db=getDBConnection();$type=($_GET['tipo']??'ingreso')==='egreso'?'egreso':'ingreso';$table=$type==='egreso'?'egresos':'ingresos_diarios';$id=(int)($_GET['editar']??0);$error='';
$enums=['tipo_ingreso'=>['consulta','vacunacion','producto','servicio','otros'],'categoria'=>$type==='egreso'?['peluqueria','servicios_veterinarios','encargada','leonel','logistica','insumos','alquileres','facturas_tienda','eco','vehiculo','laboratorio','hogar','fondo_ahorro','fumigacion']:['peluqueria','servicios_veterinarios','tienda','laboratorio','ecografia','fumigacion'],'metodo_pago'=>['efectivo','transferencia','tarjeta','cheque'],'estado'=>['pendiente','pagado']];
$columns=$type==='egreso'?['fecha','categoria','proveedor','descripcion','monto','metodo_pago','numero_factura','estado']:['fecha','tipo_ingreso','descripcion','monto','categoria'];
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST')try{
 if($id<1)throw new RuntimeException('Seleccione un registro para editar.');$values=[];
 foreach($columns as $c){$v=trim($_POST[$c]??'');if($c!=='numero_factura'&&$v==='')throw new RuntimeException('Complete todos los campos obligatorios.');if(isset($enums[$c])&&!in_array($v,$enums[$c],true))throw new RuntimeException('Opción no válida.');if($c==='fecha'&&!av_valid_date($v))throw new RuntimeException('Fecha no válida.');if($c==='monto'&&av_money($v)<=0)throw new RuntimeException('El importe debe ser mayor a cero.');$values[]=$v;}
 $db->prepare("UPDATE `$table` SET ".implode(',',array_map(fn($c)=>"`$c`=?",$columns)).' WHERE id=?')->execute([...$values,$id]);header('Location: movimientos.php?tipo='.$type);exit;
}catch(Throwable $e){$error=$e instanceof PDOException?'No se pudo guardar el movimiento.':$e->getMessage();}
$row=null;if($id){$q=$db->prepare("SELECT * FROM `$table` WHERE id=?");$q->execute([$id]);$row=$q->fetch();if(!$row)av_fail('Movimiento no encontrado.',404);}
$search=trim($_GET['buscar']??'');$page=max(1,(int)($_GET['pagina']??1));$offset=($page-1)*40;$q=$db->prepare("SELECT * FROM `$table` WHERE descripcion LIKE ? ORDER BY fecha DESC,id DESC LIMIT 40 OFFSET $offset");$q->execute(['%'.$search.'%']);$rows=$q->fetchAll();
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Movimientos manuales</title><?php av_head();?></head><body><?php include __DIR__.'/sidebar.php';?><main class="av-page"><h1>Movimientos manuales</h1><p><a href="?tipo=ingreso">Ingresos</a> · <a href="?tipo=egreso">Egresos</a> · <a href="<?=$type==='egreso'?'egresos.php':'ingresos.php'?>">Registrar <?=$type?></a></p><?php if($error):?><p class="av-error"><?=e($error)?></p><?php endif;?>
<?php if($row):?><form class="av-card" method="post"><?=av_csrf_field()?><h2>Editar <?=$type?> #<?=$id?></h2><div class="av-grid"><?php foreach($columns as $c):?><div><label for="<?=e($c)?>"><?=e(ucfirst(str_replace('_',' ',$c)))?></label><?php if(isset($enums[$c])):?><select id="<?=e($c)?>" name="<?=e($c)?>"><?php foreach($enums[$c] as $v):?><option value="<?=e($v)?>" <?=$row[$c]===$v?'selected':''?>><?=e(ucfirst(str_replace('_',' ',$v)))?></option><?php endforeach;?></select><?php else:?><input id="<?=e($c)?>" name="<?=e($c)?>" value="<?=e($row[$c])?>" type="<?=$c==='fecha'?'date':($c==='monto'?'number':'text')?>" <?=$c==='monto'?'min="0.01" step="0.01"':''?> <?=$c==='numero_factura'?'':'required'?>><?php endif;?></div><?php endforeach;?></div><p><button>Guardar cambios</button></p></form><?php endif;?>
<form method="get" class="av-card"><input type="hidden" name="tipo" value="<?=$type?>"><label>Buscar descripción</label><input name="buscar" value="<?=e($search)?>"><button>Buscar</button></form><div class="av-card"><table><thead><tr><th>Fecha</th><th>Descripción</th><th>Monto USD</th><th>Acciones</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['fecha'])?></td><td><?=e($r['descripcion'])?></td><td><?=number_format((float)$r['monto'],2)?></td><td><a href="?tipo=<?=$type?>&editar=<?=(int)$r['id']?>">Editar</a><?php if(auth_current_role()==='admin'):?> · <a href="eliminar_registro.php?tipo=<?=$type?>&id=<?=(int)$r['id']?>">Eliminar</a><?php endif;?></td></tr><?php endforeach;?></tbody></table><?php if(!$rows):?><p>No hay movimientos.</p><?php endif;?></div><p><?php if($page>1):?><a href="?tipo=<?=$type?>&pagina=<?=$page-1?>&buscar=<?=urlencode($search)?>">Anterior</a> · <?php endif;?>Página <?=$page?><?php if(count($rows)===40):?> · <a href="?tipo=<?=$type?>&pagina=<?=$page+1?>&buscar=<?=urlencode($search)?>">Siguiente</a><?php endif;?></p></main></body></html>
